61: /// is active, since those determine the valid address and low-bit encodings.
62: /// Encode a replacement CR3 value while preserving the active low-bit mode.
63: ///
64: /// PCID is retained but the no-flush bit is always cleared so the selected PCID
65: /// is invalidated on load. Legacy PWT/PCD controls are preserved unchanged.
66: pub fn encode_cr3_value(
67:     root_physical_address: u64,
68:     low_bits: Cr3LowBits,
69:     physical_address_bits: u8,
70: ) -> Result<u64, Cr3Error> {
71:     if !(12..=MAX_PTE_PHYSICAL_ADDRESS_BITS).contains(&physical_address_bits) {
72:         return Err(Cr3Error::InvalidPhysicalAddressWidth);
73:     }
74:     let root_end = root_physical_address
75:         .checked_add(PAGE_SIZE)
76:         .ok_or(Cr3Error::InvalidRootAddress)?;
77:     if root_physical_address & (PAGE_SIZE - 1) != 0
78:         || !physical_range_fits_address_width(
79:             root_physical_address,
80:             root_end,
81:             physical_address_bits,
82:         )
83:     {
84:         return Err(Cr3Error::InvalidRootAddress);
85:     }
86:     let low = match low_bits {
87:         Cr3LowBits::Pcid(pcid) if pcid <= 0x0fff => u64::from(pcid),
88:         Cr3LowBits::Pcid(_) => return Err(Cr3Error::ReservedBits),
89:         Cr3LowBits::CacheControls {
90:             page_level_write_through,
91:             page_level_cache_disable,
92:         } => {
93:             (u64::from(page_level_write_through) << 3) | (u64::from(page_level_cache_disable) << 4)
94:         }
95:     };
96:     Ok(root_physical_address | low)
97: }
