105:         physical_address_bits.ok_or(Cr3Error::UnknownPhysicalAddressWidth)?;
106:     if !(12..=MAX_PTE_PHYSICAL_ADDRESS_BITS).contains(&physical_address_bits) {
107:         return Err(Cr3Error::InvalidPhysicalAddressWidth);
108:     }
109: 
110:     let physical_mask = ((1u64 << physical_address_bits) - 1) & !(PAGE_SIZE - 1);
111:     let low_mask = if pcid_enabled {
112:         PAGE_SIZE - 1
113:     } else {
114:         (1 << 3) | (1 << 4)
115:     };
116:     if raw & !(physical_mask | low_mask) != 0 {
117:         return Err(Cr3Error::ReservedBits);
118:     }
