120:     let low_bits = if pcid_enabled {
121:         Cr3LowBits::Pcid((raw & (PAGE_SIZE - 1)) as u16)
122:     } else {
123:         Cr3LowBits::CacheControls {
124:             page_level_write_through: raw & (1 << 3) != 0,
125:             page_level_cache_disable: raw & (1 << 4) != 0,
126:         }
127:     };
128: 
129:     Ok(Cr3Root {
130:         physical_address: raw & physical_mask,
131:         low_bits,
132:     })
133: }
