149:         .checked_add(PAGE_SIZE)
150:         .ok_or(Cr3RootAccessError::Hhdm(HhdmAddressError::AddressOverflow))?;
151:     if !memory_map.range_is_within_region_kind(
152:         physical_start,
153:         physical_end,
154:         RegionKind::BootloaderReclaimable,
155:     ) {
156:         return Err(Cr3RootAccessError::NotBootloaderReclaimable);
157:     }
158:     memory_map
159:         .limine_hhdm_address(
160:             hhdm_offset,
161:             physical_start,
162:             PAGE_SIZE,
163:             physical_address_bits,
164:             virtual_address_bits,
165:         )
166:         .map_err(Cr3RootAccessError::Hhdm)
167: }
